def canSumToTarget(array, target): 
    if target == 0: 
        return True

    n = len(array) 

    # dp[i][j] stores if number j can be  
    # represented by a subset of array[0..i-1] 
    dp = [[False for j in range(target + 1)] 
            for i in range(n + 1)] 

    # Initialize base case in dp array 
    for i in range(n + 1): 
        dp[i][0] = True

    for i in range(1, n + 1): 
        for j in range(1, target + 1): 
            if j >= array[i-1]: 
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - array[i-1]] 
            else: 
                dp[i][j] = dp[i - 1][j] 

    return dp[n][target] 

# Driver Code 
array = [4, 8, 15, 16, 23, 42] 
target = 50
if canSumToTarget(array, target): 
    print('Target number can be obtained by adding elements in the array.') 
else: 
    print('Target number cannot be obtained by adding elements in the array.')
```

