def bubble_sort(list):
  for i in range(len(list)-1):
    for j in range(len(list)-i-1):
      if list[j] > list[j+1]:
        temp = list[j]
        list[j] = list[j+1]
        list[j+1] = temp
  return list

print(bubble_sort([9, 4, 5, 1, 0])) // [0, 1, 4, 5, 9]
